import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col, Button } from "reactstrap";
import "../Styles/PostJob.css";

const SECTORS = [
  "Private Company (Dhofar)",
  "Government / Ministry",
  "Small Business",
  "Non-profit",
];

const CATEGORIES = [
  "Design",
  "Marketing",
  "Education",
  "Technology",
  "Customer Service",
];

const PostJob = () => {
  const [jobTitle, setJobTitle] = useState("");
  const [organization, setOrganization] = useState("");
  const [sector, setSector] = useState(SECTORS[0]);
  const [category, setCategory] = useState(CATEGORIES[0]);
  const [rate, setRate] = useState("");
  const [rateType, setRateType] = useState("Per Hour");
  const [payout, setPayout] = useState("End of day");
  const [skills, setSkills] = useState("");
  const [description, setDescription] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const newJob = {
      jobTitle,
      organization,
      sector,
      category,
      rate,
      rateType,
      payout,
      skills,
      description,
    };
    const existing = JSON.parse(localStorage.getItem("jobs")) || [];
    existing.push(newJob);
    localStorage.setItem("jobs", JSON.stringify(existing));
    alert("✅ Job Posted Successfully!");
    e.target.reset();
  };

  const handleClear = () => {
    setJobTitle("");
    setOrganization("");
    setRate("");
    setSkills("");
    setDescription("");
  };

  return (
    <div className="postjob-page">
      <div className="postjob-card">
        <h1 className="page-title">
          Post a <span className="accent">Job</span>
        </h1>
        <p className="page-sub">
          List a part-time or internship opportunity. Choose payout rules and
          mark if training is available.
        </p>

        <Form onSubmit={handleSubmit}>
          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Job Title</Label>
                <Input
                  type="text"
                  placeholder="e.g. Reception Assistant"
                  value={jobTitle}
                  onChange={(e) => setJobTitle(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Organization</Label>
                <Input
                  type="text"
                  placeholder="Your company / ministry"
                  value={organization}
                  onChange={(e) => setOrganization(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Sector</Label>
                <Input
                  type="select"
                  value={sector}
                  onChange={(e) => setSector(e.target.value)}
                >
                  {SECTORS.map((s) => (
                    <option key={s}>{s}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Category</Label>
                <Input
                  type="select"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                >
                  {CATEGORIES.map((c) => (
                    <option key={c}>{c}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={4}>
              <FormGroup>
                <Label>Rate (OMR)</Label>
                <Input
                  type="number"
                  value={rate}
                  onChange={(e) => setRate(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
            <Col md={4}>
              <FormGroup>
                <Label>Rate Type</Label>
                <Input
                  type="select"
                  value={rateType}
                  onChange={(e) => setRateType(e.target.value)}
                >
                  <option>Per Hour</option>
                  <option>Per Task</option>
                  <option>Per Day</option>
                </Input>
              </FormGroup>
            </Col>
            <Col md={4}>
              <FormGroup>
                <Label>Payout</Label>
                <Input
                  type="select"
                  value={payout}
                  onChange={(e) => setPayout(e.target.value)}
                >
                  <option>End of day</option>
                  <option>Weekly</option>
                  <option>After completion</option>
                </Input>
              </FormGroup>
            </Col>
          </Row>

          <FormGroup>
            <Label>Skills</Label>
            <Input
              type="text"
              placeholder="e.g. Arabic, MS Office"
              value={skills}
              onChange={(e) => setSkills(e.target.value)}
            />
          </FormGroup>

          <FormGroup>
            <Label>Description</Label>
            <Input
              type="textarea"
              placeholder="Responsibilities, schedule, deliverables"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </FormGroup>

          <div className="actions">
            <button type="submit" className="btn-primary">
              + Post Job
            </button>
            <button type="button" onClick={handleClear} className="btn-ghost">
              Clear
            </button>
          </div>
        </Form>
      </div>
    </div>
  );
};

export default PostJob;
